SELECT inquiry_id, inquiry_number, category, title, status, created_at
FROM inquiry

    member_id = #{memberId}

        AND status = #{status}


ORDER BY created_at DESC, inquiry_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT inquiry_id, inquiry_number, category, title, content, reply_email, status, answer, created_at, answered_at
FROM inquiry
WHERE inquiry_id = #{inquiryId} AND member_id = #{memberId}

SELECT inquiry_id, inquiry_number, category, title, status, created_at
FROM inquiry


        status = #{status}


ORDER BY created_at DESC, inquiry_id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT inquiry_id, inquiry_number, category, title, content, reply_email, status, answer, created_at, answered_at
FROM inquiry
WHERE inquiry_id = #{inquiryId}

mapper.update:
UPDATE inquiry
SET answer = #{answer}, status = 'ANSWERED', answered_at = CURRENT_TIMESTAMP
WHERE inquiry_id = #{inquiryId}
